use vstd::prelude::*;

verus! {
    // all_prefixes produces, for an input vector s of length N,
    // exactly the N nonempty prefixes of s:
    //   result.len() == s.len()
    //   ∀ i < s.len(): result[i].len() == i+1
    //   ∀ i< s.len(), j ≤ i: result[i][j] == s[j]
    fn all_prefixes(s: Vec<char>) -> Vec<Vec<char>>
        ensures
            // result has the same number of prefixes as s has characters
            result.len() == s.len(),
            // each prefix i has length i+1
            forall|i: nat| i < s.len() ==> result[i].len() == i + 1,
            // and matches the first i+1 characters of s
            forall|i: nat, j: nat| i < s.len() && j <= i ==> result[i][j] == s[j],
    {
        let mut result: Vec<Vec<char>> = Vec::with_capacity(s.len());
        let mut prefix: Vec<char> = Vec::new();
        let mut idx: usize = 0;

        // We convert the `for c in s { … }` into the equivalent while‐loop
        // so that we can give a precise loop invariant.
        while idx < s.len()
            invariant
                // loop counter stays in [0, s.len()]
                idx <= s.len(),
                // prefix.len() == idx
                prefix.len() == idx,
                // prefix matches s[0..idx]
                forall|j: nat| j < idx ==> prefix[j] == s[j],
                // we have produced exactly idx prefixes so far
                result.len() == idx,
                // and each of those prefixes is correct
                forall|i: nat, j: nat| i < idx && j <= i ==> result[i][j] == s[j],
            decreases s.len() - idx,
        {
            let c = s[idx];
            prefix.push(c);
            result.push(prefix.clone());
            idx += 1;
        }

        result
    }

    fn main() {
        let v1: Vec<char> = vec!['a', 'b', 'c', 'd'];
        let p1 = all_prefixes(v1);
        // p1 == [["a"], ["a","b"], ["a","b","c"], ["a","b","c","d"]]

        let v2: Vec<char> = vec![];
        let p2 = all_prefixes(v2);
        // p2 == []

        println!("{:?}", p1);
        println!("{:?}", p2);
    }
}